import sys, os, struct; sys.path.insert(0,'/tmp/h')
from probe import *
from dnsbuild import *

def mkresp(nm, ttl, ip):
    return hdr(an=1) + question(nm,1) + rr(nm,1,1,ttl,bytes(ip))

# two domains -> two queries
def respfn(req, i):
    if i == 0:
        return mkresp('short.net', 1, [1,1,1,1])
    else:
        return mkresp('averyveryverylongname.example.com', 86400, [2,2,2,2])

o,e,rc,reqs = run(['short.net','averyveryverylongname.example.com','-n','127.0.0.1:@PORT@','--edns','disable'], respfn, count=2)
print("rc",rc)
for line in o.decode().split('\n'):
    print(repr(line))
print("ERR", repr(e.decode()))
EOF
